-- Explicit 2026-10-07 launch. Stage inactive rows, then switch the active bank in ONE guarded UPDATE.
-- Never deletes questions/reports or changes prices. Reruns do not overwrite admin text.
-- Verify exactly 20 launch rows active afterward; a failed gate leaves the current active bank intact.

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q01','attachment-style','Distance and uncertainty','Their replies are shorter than usual today. What happens inside you first?','','[{"label":"I start wondering whether I did something wrong and look for reassurance.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I pull my attention back and become less interested in reaching out.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I notice the change and check in before deciding what it means.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I want to ask what''s wrong, then hold back because I feel too exposed.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',1,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q02','attachment-style','Distance and uncertainty','They cancel a plan you were looking forward to. What is your first response?','','[{"label":"I wonder how important I am to them and want another plan right away.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I feel disappointed, then decide to expect less and do my own thing.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I say I''m disappointed and ask whether we can choose another time.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I act like it doesn''t matter while wanting them to notice that it does.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',2,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q03','attachment-style','Distance and uncertainty','They ask for an evening alone after a busy week. What feels most familiar?','','[{"label":"I say okay but look for signs that we''re still close.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I feel relieved and put off thinking about when we''ll reconnect.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I can give them space and agree on when we''ll catch up.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I want to respect the space, then feel hurt and want distance myself.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',3,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q04','attachment-style','Distance and uncertainty','You reconnect after a few days apart. How do you usually settle back in?','','[{"label":"I need extra warmth before I can stop wondering if something changed.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I take a while to let them back into the routine I''ve built alone.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I enjoy reconnecting and talk about anything that felt off.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I want closeness, but feel guarded once it''s available again.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',4,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q05','attachment-style','Closeness and care','They become more affectionate as the relationship grows. What do you notice?','','[{"label":"I love it and soon want to know it will keep happening.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I like them, but start protecting more time and space for myself.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I enjoy it and speak up if I need a different pace.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I feel drawn in, then uneasy about how much it matters to me.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',5,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q06','attachment-style','Closeness and care','You''re having a hard week and they offer practical help. What do you do?','','[{"label":"I accept and look for extra signs that they don''t mind helping.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I usually say I''m fine and handle it myself.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I tell them what would help and accept what they can offer.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I want the help, then feel uncomfortable once I''m relying on it.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',6,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q07','attachment-style','Closeness and care','You''ve just shared something personal with them. What happens afterward?','','[{"label":"I watch their reaction closely and wonder whether I said too much.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I change the subject and keep the next conversation lighter.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I feel a little exposed but can let their response unfold.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I feel closer for a moment, then want to take back what I shared.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',7,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q08','attachment-style','Closeness and care','You both start talking about making the relationship official. What comes up?','','[{"label":"I want a clear commitment soon so I know where I stand.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I focus on what I might lose if our lives become more connected.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I say what I want and ask whether our pace works for both of us.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I want the commitment and feel nervous about being fully known.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',8,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q09','attachment-style','Disagreement and repair','A disagreement is getting more tense. What is your usual first move?','','[{"label":"I keep talking because leaving it unresolved feels harder than continuing.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I get quiet or leave before I can say much about what I feel.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I ask for a short pause and name when I can return.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I want them close, then push them away when the feelings get stronger.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',9,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q10','attachment-style','Disagreement and repair','They say something you did hurt them. What do you notice first?','','[{"label":"I worry they''re losing trust in me and hurry to make things okay.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I focus on explaining my reasons before hearing the whole impact.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I want to understand what hurt, even if part of me feels defensive.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I want to repair it but also feel like shutting the conversation down.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',10,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q11','attachment-style','Disagreement and repair','You agreed to come back to a difficult conversation later. What usually happens?','','[{"label":"I reach out before the agreed time because the waiting is hard.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"Once I feel calmer, I hope we won''t need to bring it up again.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I return at the agreed time, or explain if I need to change it.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I prepare to talk, then hesitate when the moment to reconnect arrives.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',11,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q12','attachment-style','Disagreement and repair','They apologize after hurting your feelings. What helps you move forward?','','[{"label":"I need more reassurance that they still care about me.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I say we''re fine but keep some emotional distance.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I can accept the apology and ask for a specific change if needed.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I want to accept it but move between trust and expecting another hurt.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',12,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q13','attachment-style','Needs and boundaries','They want to see you tonight, but you need time to yourself. What do you do?','','[{"label":"I consider saying yes because I worry a no will disappoint them.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I make myself unavailable without saying much about why.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I say I need the evening and suggest another time if I want one.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I want them to want me, yet feel tense about agreeing to the plan.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',13,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q14','attachment-style','Needs and boundaries','You wish they would check in more often. How do you bring it up?','','[{"label":"I hint at it and watch for signs they''ll offer without being asked.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I tell myself it shouldn''t matter and try to need less.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I describe what would feel good and ask what works for them.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I start to ask, then soften it so much that the need disappears.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',14,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q15','attachment-style','Needs and boundaries','You discover a preference that matters to you is different from theirs. What follows?','','[{"label":"I feel tempted to change mine so we don''t become less close.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I take it as a reason to keep more of my life separate.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I can stay curious and see where we can meet without agreeing on everything.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I want to compromise, then worry I''m giving up too much of myself.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',15,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q16','attachment-style','Needs and boundaries','They''ve had a rough day and want to talk. What is your first reaction?','','[{"label":"I feel responsible for helping them feel better quickly.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I move into advice or practical fixes rather than staying with the feeling.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I ask whether they want listening, help, or a little space.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I want to comfort them but also feel overwhelmed and want to step back.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',16,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q17','attachment-style','Stability and reflection','The relationship has felt steady for several weeks. What do you notice?','','[{"label":"I still look for reassurance that the warmth hasn''t started to fade.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I begin noticing reasons I might want more distance.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I feel able to enjoy the relationship and the rest of my life.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I enjoy the calm but catch myself bracing for it to change.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',17,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q18','attachment-style','Stability and reflection','They spend an evening with friends while you do your own thing. What feels familiar?','','[{"label":"I have trouble settling unless we check in during the evening.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I feel most comfortable when our plans don''t depend on each other.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I can enjoy separate plans and look forward to catching up.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I want the independence, then feel unexpectedly left out once we''re apart.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',18,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q19','attachment-style','Stability and reflection','You realize you made a mistake in the relationship. What do you tend to do?','','[{"label":"I apologize repeatedly and need to know they still want me.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I focus on fixing the practical part and avoid discussing how it felt.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"I own what I did, listen to the impact, and follow through on a change.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"I want to make amends but feel like hiding before they can respond.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',19,0) ON CONFLICT(id) DO NOTHING;

INSERT INTO quiz_questions (id,test_id,kicker,prompt,atlas_path,options_json,position,active) VALUES ('attachment-style-launch-v1-q20','attachment-style','Stability and reflection','After a reassuring conversation, how long does the reassurance stay with you?','','[{"label":"It helps briefly, then a small change makes me need it again.","styleKey":"anxious","microcopy":"","meaning":"","projection":""},{"label":"I feel calmer mainly once I have some time to myself.","styleKey":"avoidant","microcopy":"","meaning":"","projection":""},{"label":"It usually stays with me unless something new gives me a reason to worry.","styleKey":"secure","microcopy":"","meaning":"","projection":""},{"label":"Part of me believes it while another part stays ready to pull away.","styleKey":"fearful","microcopy":"","meaning":"","projection":""}]',20,0) ON CONFLICT(id) DO NOTHING;

UPDATE quiz_questions SET active=CASE WHEN id IN ('attachment-style-launch-v1-q01','attachment-style-launch-v1-q02','attachment-style-launch-v1-q03','attachment-style-launch-v1-q04','attachment-style-launch-v1-q05','attachment-style-launch-v1-q06','attachment-style-launch-v1-q07','attachment-style-launch-v1-q08','attachment-style-launch-v1-q09','attachment-style-launch-v1-q10','attachment-style-launch-v1-q11','attachment-style-launch-v1-q12','attachment-style-launch-v1-q13','attachment-style-launch-v1-q14','attachment-style-launch-v1-q15','attachment-style-launch-v1-q16','attachment-style-launch-v1-q17','attachment-style-launch-v1-q18','attachment-style-launch-v1-q19','attachment-style-launch-v1-q20') THEN 1 ELSE 0 END, updated_at=CURRENT_TIMESTAMP WHERE test_id='attachment-style' AND ((SELECT COUNT(*) FROM quiz_questions WHERE test_id='attachment-style' AND active=1)=20 AND NOT EXISTS (SELECT 1 FROM quiz_questions WHERE test_id='attachment-style' AND active=1 AND id NOT IN ('attachment-style-v3-q01','attachment-style-v3-q02','attachment-style-v3-q03','attachment-style-v3-q04','attachment-style-v3-q05','attachment-style-v3-q06','attachment-style-v3-q07','attachment-style-v3-q08','attachment-style-v3-q09','attachment-style-v3-q10','attachment-style-v3-q11','attachment-style-v3-q12','attachment-style-v3-q13','attachment-style-v3-q14','attachment-style-v3-q15','attachment-style-v3-q16','attachment-style-v3-q17','attachment-style-v3-q18','attachment-style-v3-q19','attachment-style-v3-q20','attachment-style-launch-v1-q01','attachment-style-launch-v1-q02','attachment-style-launch-v1-q03','attachment-style-launch-v1-q04','attachment-style-launch-v1-q05','attachment-style-launch-v1-q06','attachment-style-launch-v1-q07','attachment-style-launch-v1-q08','attachment-style-launch-v1-q09','attachment-style-launch-v1-q10','attachment-style-launch-v1-q11','attachment-style-launch-v1-q12','attachment-style-launch-v1-q13','attachment-style-launch-v1-q14','attachment-style-launch-v1-q15','attachment-style-launch-v1-q16','attachment-style-launch-v1-q17','attachment-style-launch-v1-q18','attachment-style-launch-v1-q19','attachment-style-launch-v1-q20')) AND ((EXISTS (SELECT 1 FROM quiz_questions WHERE id='attachment-style-v3-q01' AND test_id='attachment-style' AND prompt='When their texting suddenly goes cold and dry, what hits you first?' AND json_extract(options_json,'$[0].label')='A sinking feeling in my chest: Did I say something wrong?' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='Perfect, peace and quiet. I just go back to my own thing.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I notice it, but casually ask: "Tough day?"' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='Panic makes me want to fix it, while another part screams: "Why am I always the one groveling?"' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS (SELECT 1 FROM quiz_questions WHERE id='attachment-style-v3-q02' AND test_id='attachment-style' AND prompt='Right after a fight or when things get dead serious, what’s your physical instinct?' AND json_extract(options_json,'$[0].label')='Fix it right now. If they ignore me, I''ll keep calling—every second feels like a breakup.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='Leave me alone. I want to shut my phone off, sleep, walk out, or just end the relationship.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='It hurts, but I can say: "Let’s both take 30 minutes to cool off, then talk."' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='Storm out the door, then freeze in the hallway staring at my phone, praying they chase after me.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS (SELECT 1 FROM quiz_questions WHERE id='attachment-style-v3-q03' AND test_id='attachment-style' AND prompt='When they don’t reply for most of the day, how are you actually doing?' AND json_extract(options_json,'$[0].label')='Checking my phone every two minutes, completely unable to focus on anything else.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='Barely noticed the time. Honestly, not having to reply instantly feels like a relief.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='Figure they''re just busy. I get on with my day and catch up with them tonight.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='Furious enough to block them, yet constantly checking their profile over and over.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS (SELECT 1 FROM quiz_questions WHERE id='attachment-style-v3-q04' AND test_id='attachment-style' AND prompt='When they suddenly get super clingy and shower you with affection, your real reaction is?' AND json_extract(options_json,'$[0].label')='Pure dopamine, but terrified it''s temporary—I need them to keep reassuring me.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='My skin crawls. I instinctively pull back—it feels way too fast and suffocating.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='Happy. I take it in naturally and enjoy the sweet moment.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='Touched for one second, then the panic hits: "What if they change their mind later?"' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS (SELECT 1 FROM quiz_questions WHERE id='attachment-style-v3-q05' AND test_id='attachment-style' AND prompt='When they’re visibly moody and giving you one-word answers, your first thought is?' AND json_extract(options_json,'$[0].label')='"Are they mad at me? What did I do wrong today?"' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='"Whoever pissed you off, go take it out on them. Don''t bring that energy to me."' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='"They probably had a rough day. I''ll ask what''s going on."' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='"Fine. You want to be cold? I can be colder. Let’s see who lasts longer."' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS (SELECT 1 FROM quiz_questions WHERE id='attachment-style-v3-q06' AND test_id='attachment-style' AND prompt='When you feel deeply hurt or upset inside, how do you usually handle it?' AND json_extract(options_json,'$[0].label')='Send massive paragraphs and vent intensely—I need an answer that calms my anxiety.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='Swallow it. I say nothing because "talking about it is pointless anyway."' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='Gather my thoughts and find a calm moment to tell them directly how I feel.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='Say "I''m fine," but secretly play out worst-case scenarios, waiting for them to notice and fix it.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS (SELECT 1 FROM quiz_questions WHERE id='attachment-style-v3-q07' AND test_id='attachment-style' AND prompt='If they cancel plans last minute or show up really late, your immediate thought is?' AND json_extract(options_json,'$[0].label')='They clearly don''t care about me. I''m just not a priority to them.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='Whatever. Honestly, I''m glad I don''t have to socialize.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='That''s annoying, but let me hear their reason first.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='Hurt meets resentment: "Am I that disposable? Fine, see if I ever show up on time for you again."' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS (SELECT 1 FROM quiz_questions WHERE id='attachment-style-v3-q08' AND test_id='attachment-style' AND prompt='When a relationship stays completely calm and stable for a long time, you feel?' AND json_extract(options_json,'$[0].label')='Anxious: Is the spark gone? Are they falling out of love with me?' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='Suffocated: it feels like a cage, and I want an excuse to be alone for a few days.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='Grounded: finally able to focus my energy on work, friends, and life.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='Restless: I''ll start picking fights just to test if they still care enough to tolerate me.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS (SELECT 1 FROM quiz_questions WHERE id='attachment-style-v3-q09' AND test_id='attachment-style' AND prompt='To ease your inner anxiety, what is your go-to defense mechanism?' AND json_extract(options_json,'$[0].label')='Dropping hints and testing them just to force out the reassurance I need to hear.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='Intentionally delaying replies or pulling away to prove I don''t need anyone.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='Being direct: stating clearly what''s making me uncomfortable.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='Pushing for answers, then suddenly going completely cold or ghosting to see if they''ll chase me.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
