EXISTS (SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q17' AND test_id='attachment-style' AND prompt='The relationship has felt steady for several weeks. What do you notice?' AND json_extract(options_json,'$[0].label')='I still look for reassurance that the warmth hasn''t started to fade.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I begin noticing reasons I might want more distance.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I feel able to enjoy the relationship and the rest of my life.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I enjoy the calm but catch myself bracing for it to change.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS (SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q18' AND test_id='attachment-style' AND prompt='They spend an evening with friends while you do your own thing. What feels familiar?' AND json_extract(options_json,'$[0].label')='I have trouble settling unless we check in during the evening.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I feel most comfortable when our plans don''t depend on each other.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I can enjoy separate plans and look forward to catching up.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I want the independence, then feel unexpectedly left out once we''re apart.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS (SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q19' AND test_id='attachment-style' AND prompt='You realize you made a mistake in the relationship. What do you tend to do?' AND json_extract(options_json,'$[0].label')='I apologize repeatedly and need to know they still want me.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I focus on fixing the practical part and avoid discussing how it felt.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='I own what I did, listen to the impact, and follow through on a change.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='I want to make amends but feel like hiding before they can respond.' AND json_extract(options_json,'$[3].styleKey')='fearful') AND
EXISTS (SELECT 1 FROM quiz_questions WHERE id='attachment-style-launch-v1-q20' AND test_id='attachment-style' AND prompt='After a reassuring conversation, how long does the reassurance stay with you?' AND json_extract(options_json,'$[0].label')='It helps briefly, then a small change makes me need it again.' AND json_extract(options_json,'$[0].styleKey')='anxious' AND json_extract(options_json,'$[1].label')='I feel calmer mainly once I have some time to myself.' AND json_extract(options_json,'$[1].styleKey')='avoidant' AND json_extract(options_json,'$[2].label')='It usually stays with me unless something new gives me a reason to worry.' AND json_extract(options_json,'$[2].styleKey')='secure' AND json_extract(options_json,'$[3].label')='Part of me believes it while another part stays ready to pull away.' AND json_extract(options_json,'$[3].styleKey')='fearful')) AND EXISTS(SELECT 1 FROM quiz_tests WHERE id='attachment-style' AND report_price_cents=999 AND active=1));

UPDATE quiz_tests SET title='Your Relationship Pattern: 20 Everyday Moments', kicker='Free · 20 first-reaction questions', description='Think of one current or recent romantic relationship. Choose the response closest to what you tend to do. Keep that same relationship in mind for all 20 questions.', presentation_mode='text', updated_at=CURRENT_TIMESTAMP WHERE id='attachment-style' AND (SELECT COUNT(*) FROM quiz_questions WHERE test_id='attachment-style' AND active=1 AND id IN ('attachment-style-launch-v1-q01','attachment-style-launch-v1-q02','attachment-style-launch-v1-q03','attachment-style-launch-v1-q04','attachment-style-launch-v1-q05','attachment-style-launch-v1-q06','attachment-style-launch-v1-q07','attachment-style-launch-v1-q08','attachment-style-launch-v1-q09','attachment-style-launch-v1-q10','attachment-style-launch-v1-q11','attachment-style-launch-v1-q12','attachment-style-launch-v1-q13','attachment-style-launch-v1-q14','attachment-style-launch-v1-q15','attachment-style-launch-v1-q16','attachment-style-launch-v1-q17','attachment-style-launch-v1-q18','attachment-style-launch-v1-q19','attachment-style-launch-v1-q20'))=20 AND NOT EXISTS (SELECT 1 FROM quiz_catalog_migrations WHERE id='attachment-launch-v1-2026-10-07');

