SELECT COUNT(*) AS active_questions, SUM(CASE WHEN id IN ('attachment-style-launch-v1-q01','attachment-style-launch-v1-q02','attachment-style-launch-v1-q03','attachment-style-launch-v1-q04','attachment-style-launch-v1-q05','attachment-style-launch-v1-q06','attachment-style-launch-v1-q07','attachment-style-launch-v1-q08','attachment-style-launch-v1-q09','attachment-style-launch-v1-q10','attachment-style-launch-v1-q11','attachment-style-launch-v1-q12','attachment-style-launch-v1-q13','attachment-style-launch-v1-q14','attachment-style-launch-v1-q15','attachment-style-launch-v1-q16','attachment-style-launch-v1-q17','attachment-style-launch-v1-q18','attachment-style-launch-v1-q19','attachment-style-launch-v1-q20') THEN 1 ELSE 0 END) AS launch_questions FROM quiz_questions WHERE test_id='attachment-style' AND active=1;
